"""RAM-only GUI notification bridge; all skin/profile/frame IO stays in worker."""
import hashlib,json,threading,time
_lock=threading.Lock();_pending={};_hooks={};_seen={};_focus=None;_next=0


def prepare(portal,kind,signature,count):
    from widget_hooks45 import read
    state=read();hooks=[]
    for binding in state.get('bindings',[])[:96]:
        if binding.get('pid')==str(portal['id']) and binding.get('kind')==kind:
            hooks.extend(h for h in binding.get('hooks',[]) if h.startswith('XCMate.Widget45.Reload.') or h in ('widgetreload','widgetreload2','widgetreloadmovies','widgetreloadtvshows'))
    with _lock:
        _hooks[(str(portal['id']),kind)]=hooks
        _pending[(str(portal['id']),kind)]=(signature,count)


def poll():
    global _next,_focus
    import xbmc,xbmcgui
    if time.monotonic()<_next:return
    _next=time.monotonic()+1
    if xbmc.getSkinDir()!='skin.titan.bingie.mod' or xbmcgui.getCurrentWindowId()!=10000:return
    if xbmcgui.getCurrentWindowDialogId() not in (0,-1,9999) or xbmc.getCondVisibility('Player.HasMedia'):return
    # Kodi's selected ListItem is already a RAM object. Never perform a source,
    # DNS, SQLite or disk query when IR focus changes.
    url=xbmc.getInfoLabel('ListItem.Property(XCMate.ProgrammeDetails46)')
    if isinstance(url,str) and len(url)<2048 and url.startswith('plugin://plugin.video.xtreammate/'):
        with _lock:_focus=url
    from widget_refresh45 import trace
    with _lock:pending=dict(_pending);hooks={k:list(v) for k,v in _hooks.items()}
    changes={}
    for key,(signature,count) in pending.items():
        if not hooks.get(key):trace('BLOCKED_NO_RELOAD_HOOK',key[1],count)
        for hook in hooks.get(key,[]):changes.setdefault(hook,[]).append((key[0],key[1],signature,count))
    now=time.monotonic();window=xbmcgui.Window(10000)
    for hook,values in changes.items():
        signature=hashlib.sha256(json.dumps(sorted(values)).encode()).hexdigest();old=_seen.get(hook)
        if old and (old[0]==signature or now-old[1]<60):continue
        window.setProperty(hook,signature);_seen[hook]=(signature,now)
        for _,kind,_,count in values:trace('UPDATED',kind,count)


def focused():
    """Drain the legacy hint; focused ListItems already contain the final URL.

    Focus must not become a second metadata resolver, even on a worker. The
    rotating background prefetcher handles NOW/NEXT independently of input.
    """
    global _focus
    with _lock:_focus=None

"""Single owner-pumped source manager and readable report on existing APIs."""
import time
from concurrent.futures import ThreadPoolExecutor
import xbmcgui
from menu_icons45 import select
from owner_dispatch import OwnerDispatch,native_init


class Manager53(OwnerDispatch,xbmcgui.WindowXMLDialog):
    _native_surface='dialog'
    def configure(self,portal):
        self._configure_owner();self.portal=portal;self._pool=ThreadPoolExecutor(max_workers=1)
        self._generation=0;self._closed=False;self.rows=[];self.mode='sources';self._last=0;self.scroll=0;self.next_action=None
    @native_init
    def onInit(self):
        self.getControl(101).setLabel('XCMate · EPG-Manager')
        for cid,label in [(401,'Quellen hinzufügen'),(402,'Jetzt aktualisieren'),(403,'Aktualisierungsbericht anzeigen'),(404,'Quellenliste'),(405,'Großes EPG / Senderzuordnung'),(406,'Zurück'),(407,'Automatisches Intervall'),(408,'Bericht nach oben'),(409,'Bericht nach unten')]:self.getControl(cid).setLabel(label)
        self._load();self.setFocusId(410 if self.portal.get('type')=='xtream' else 401)
    def _load(self):
        from epg_report53 import overview
        self.mode='sources';self.getControl(300).setVisible(False);self.getControl(200).setVisible(True)
        self.getControl(102).setLabel('Gespeicherte Quellen werden gelesen …')
        def load():
            from wizard_epg54 import pending
            from portals import get_by_id
            portal=get_by_id(self.portal['id']) or self.portal
            return portal,overview(portal),pending(portal)
        def ready(value):
            self.portal,rows,self._setup_pending54=value;self._loaded(rows)
        self._request(load,ready)
    def _loaded(self,rows):
        from epg_report53 import meaning
        self.getControl(410).setLabel('Anbieter-EPG deaktivieren' if self.portal.get('provider_epg_enabled',True) else 'Anbieter-EPG aktivieren')
        self.getControl(410).setEnabled(self.portal.get('type')=='xtream')
        self.rows=rows;control=self.getControl(200);pos=control.getSelectedPosition();control.reset()
        items=[]
        for row in rows:
            saved=row['saved'];counts=(str(saved.get('channels',0))+' Sender · '+str(saved.get('programmes',0))+' Sendungen') if row['statistics_code']=='READY' else 'Bestand derzeit nicht sicher lesbar'
            items.append(xbmcgui.ListItem(('✓ ' if row['enabled'] else '○ ')+str(row['rank'])+' · '+row['name'],label2=meaning(row['code'])+' · '+counts))
        control.addItems(items)
        if items:control.selectItem(min(pos,len(items)-1))
        from epg_schedule53 import interval
        self.getControl(102).setLabel('Automatisch alle '+str(interval()//3600)+' Stunden · OK: Quelle verwalten · Einzelzuordnung im großen EPG')
        self.getControl(402).setLabel('EPG-Einrichtung fortsetzen' if getattr(self,'_setup_pending54',False) else 'Jetzt aktualisieren')
        self._detail()
    def _detail(self):
        if self.mode!='sources' or not self.rows:return
        row=self.rows[min(self.getControl(200).getSelectedPosition(),len(self.rows)-1)]
        from epg_report53 import stamp
        saved=row['saved']
        self.getControl(103).setText('Letzter Erfolg: '+stamp(row['last_success'])+'\nLetzter protokollierter Fehler: '+stamp(row['last_failure'])+'\nGespeicherter Zeitraum: '+stamp(saved.get('first'))+' bis '+stamp(saved.get('last')))
    def onFocus(self,cid):
        if cid==200:self._detail()
    def _query_failed(self,exc):self.getControl(102).setLabel('EPG-Zugriff oder Speichern nicht bestätigt. Daten bleiben erhalten.')
    def _reports(self):
