"""Session-scoped explicit TV exit; callbacks request, service stops/returns."""
import hashlib,json,time
from urllib.parse import urlencode
import xbmc,xbmcgui
KEY='XCMate.LiveExit'
SESSION='XtreamMate.LiveSession'


def _marker():return xbmcgui.Window(10000)


def state():
    try:
        value=json.loads(_marker().getProperty(KEY))
        from playback_exit import _session
        if isinstance(value,dict) and _session(json.dumps(value.get('session'))) and value.get('phase') in ('requested','stopping','home','complete','failed') and 0<=time.time()-value['at']<86400:return value
    except (ValueError,TypeError,KeyError):pass
    return None


def _save(value):_marker().setProperty(KEY,json.dumps(value))


def _trace(stage,session=None):
    # Stable correlation without clear portal, sender, nonce or URL in the log.
    digest=hashlib.sha256(json.dumps(['live',(session or {}).get('nonce')]).encode()).hexdigest()[:12]
    try:
        xbmc.log('[XCMate][LIVE_EXIT] stage='+stage+' session='+digest+
                 ' window='+str(int(xbmcgui.getCurrentWindowId())),xbmc.LOGINFO)
    except (AttributeError,RuntimeError):pass


def new_selection():
    # Called by an actual resolver/tune announcement; service URL-recovery is
    # suppressed while this intent exists and cannot create this selection.
    _marker().clearProperty(KEY)


def request(navigator,reason='USER_BACK'):
    if getattr(navigator,'_exiting',False):return True
    from playback_exit import identity,_same
    player=xbmc.Player();token=identity(player)
    if token is None and not player.isPlayingVideo():token=getattr(navigator,'_owned_token',None)
    if not token or token[0]!='live' or token[1]['pid']!=str(navigator.portal['id']):return False
    from live_overlay import session_from_property
    announced=session_from_property(_marker().getProperty(SESSION))
    pending=None
    if announced and not _same(token,('live',announced)):
        previous=getattr(navigator,'_previous_session',None)
        if not (previous and _same(token,('live',previous)) and announced['pid']==str(navigator.portal['id']) and announced['sid']==navigator.sid):return False
        pending={k:announced[k] for k in ('pid','sid','nonce','at')}
    prior=state()
    if prior and _same(('live',prior['session']),token):
        # The latch belongs to the session, not one Python WindowDialog. A
        # reconstructed/reentrant navigator cannot replay Stop/Home or reset
        # an already committed phase/deadline.
        navigator._exiting=True;navigator._exit_nonce=token[1]['nonce']
        return True
    value=dict(session={k:token[1][k] for k in ('pid','sid','nonce','at')},phase='requested',at=time.time(),deadline=time.monotonic()+5,not_before=time.monotonic()+.15)
    if token[1].get('origin_window48')==10000:value['origin_window48']=10000
    value['pending']=pending;value['reason']=reason if reason in ('USER_BACK','USER_STOP','USER_HOME') else 'USER_BACK'
    _save(value);navigator._exiting=True;navigator._exit_nonce=token[1]['nonce']
    _marker().setProperty('XCMate.PrePlay.Cancel',(pending or token[1])['nonce'])
    _trace('STOP_REQUESTED',token[1]);return True


def _poll(navigator=None):
    value=state()
    if value is None:
        # A consciously selected new session replaces the old exiting dialog.
        if navigator is not None and getattr(navigator,'_exiting',False):navigator.close()
        return False
    session=value['session'];marker=_marker()
    from live_overlay import session_from_property
    current=session_from_property(marker.getProperty(SESSION))
    allowed=[session]+([value['pending']] if value.get('pending') else [])
    if current and not any(current['nonce']==item['nonce'] for item in allowed):
        if navigator is not None and getattr(navigator,'_exiting',False):navigator.close()
        marker.clearProperty(KEY);return False
    from exit_jobs import blocked
    if blocked():return True
    from exit_jobs import state as job_state
    job=job_state()
    from live_trace48 import observe as observe_return48
    observe_return48(value,job)
    if job and job['phase'] in ('failed','timeout') and job['token'][1]['nonce']==session['nonce']:
        from live_recovery46 import resume
        if resume(value,job):return True
        if value.get('recovery46')=='LATE_ACK_VERIFIED':
            pass  # Continue the existing Stop-done/Home path, never repost Stop.
        else:
            if value['phase']!='failed':
                value['phase']='failed';_save(value);_trace('STOP_TIMEOUT' if job['phase']=='timeout' else 'STOP_REJECTED',session)
                if navigator is not None and not navigator._closed:navigator.close()
            return True  # Native timeout remains a recorded failure.
    player=xbmc.Player()
    from playback_exit import identity,_same
    from exit_jobs import request as stop_owned
    if value['phase'] in ('complete','failed'):
        # A past live Exit must not disable media_progress/playback_exit for
        # a later movie or a foreign add-on. Keep the root-autoplay tombstone.
        return not player.isPlayingVideo() or any(_same(identity(player),('live',item)) for item in allowed)
    token=identity(player)
    playing=player.isPlaying() if hasattr(player,'isPlaying') else player.isPlayingVideo()
    if playing and token is None and value['phase']=='stopping' and job and job.get('worker_done') and job.get('result')=='complete' and job['token'][1]['nonce']==session['nonce']:
        # Kodi can invalidate its InfoTag during a real Stop. Unknown state is
        # not evidence of foreign playback, and never authorizes another Stop.
        if time.monotonic()>value['deadline']:
            value['phase']='failed';_save(value);_trace('PLAYER_UNAVAILABLE',session)
        elif not value.get('player_wait47'):
            value['player_wait47']=True;_save(value);_trace('PLAYER_STATE_PENDING47',session)
        return True
    if playing and not any(_same(token,('live',item)) for item in allowed):
        # Foreign playback must neither receive stop nor a GUI navigation.
        if navigator is not None and getattr(navigator,'_exiting',False):navigator.close()
        value['phase']='failed';_save(value);_trace('FOREIGN_PLAYER',session);return True
    if value['phase']=='requested':
        if time.monotonic()<value['not_before']:return True
        # Commit before invoking native Stop; reentrant ticks cannot stop twice.
        value['phase']='stopping';_save(value)
        # Release the native overlay BEFORE scheduling Stop on a later tick.
        # Never wait on Player.stop while owning the live dialog.
        if navigator is not None and not navigator._closed:navigator.close()
        if playing:
            if not stop_owned(player,expected=token,reason=value.get('reason','USER_BACK')):
                value['phase']='failed';_save(value)
                if navigator is not None and not navigator._closed:navigator.close()
                _trace('OWNERSHIP_CHANGED',session);return True
        _trace('STOP_QUEUED',session)
        return True
    if player.isPlayingVideo() or (hasattr(player,'isPlaying') and player.isPlaying()):
        if time.monotonic()>value['deadline']:
            value['phase']='failed';_save(value)
            if navigator is not None and not navigator._closed:navigator.close()
            _trace('STOP_TIMEOUT',session)
            xbmcgui.Dialog().notification('XCMate','Live-TV konnte nicht beendet werden.')
        return True
    if value['phase']=='stopping':
        if navigator is not None and not navigator._closed:navigator.close()
        for key in ('XCMate.PrePlay.Request','XCMate.PrePlay.Ack','XCMate.PrePlay.Ready',SESSION,'XtreamMate.RemoteCommand'):
            raw=marker.getProperty(key)
            if key=='XtreamMate.RemoteCommand' or raw in [item['nonce'] for item in allowed] or (session_from_property(raw) or {}).get('nonce') in [item['nonce'] for item in allowed]:marker.clearProperty(key)
        value['phase']='home';_save(value);_trace('STOP_DONE',session)
        return True  # Native close returns before navigation on a later tick.
    if value.get('recovery46')=='LATE_ACK_VERIFIED':
        from live_recovery46 import gui_available
        if not gui_available():return True
    from live_return47 import guard as return_guard47
    status47,fresh47=return_guard47(value)
    if status47!='READY':
        _trace('RETURN_'+status47+'47',session)
        return True
    value=fresh47
    if xbmc.getCondVisibility('System.HasActiveModalDialog'):
        if time.monotonic()>value['deadline']:value['phase']='failed';_save(value);_trace('RETURN_BLOCKED',session)
        return True
    if getattr(xbmc.Monitor(),'abortRequested',lambda:False)():return True
    from live_trace48 import return_home as widget_return48
    returned48=widget_return48(value)
    if returned48 is None:return True
    value['phase']='complete';_save(value)
    if returned48:
        _trace('HOME_WIDGET_RETURN48',session);return True
    url='plugin://plugin.video.xtreammate/?'+urlencode(dict(action='xcmate_home',pid=session['pid']))
    from urllib.parse import urlsplit,parse_qs
    folder=urlsplit(xbmc.getInfoLabel('Container.FolderPath'))
    params=parse_qs(folder.query)
    same_home=(folder.scheme=='plugin' and folder.netloc=='plugin.video.xtreammate'
               and params.get('action')==['xcmate_home'] and params.get('pid')==[session['pid']])
    if same_home:
        # Reveal the existing Videos Home without issuing another GetDirectory.
        if not xbmc.getCondVisibility('Window.IsActive(videos)'):
            xbmc.executebuiltin('ActivateWindow(Videos)')
        _trace('HOME_REUSED',session)
    elif xbmc.getCondVisibility('Window.IsActive(videos)'):
        xbmc.executebuiltin('Container.Update('+url+',replace)')
    else:xbmc.executebuiltin('ActivateWindow(Videos,'+url+',return)')
    if not same_home:_trace('HOME_REQUESTED',session)
    return True


def poll(navigator=None):
    try:return _poll(navigator)
    except (AttributeError,RuntimeError,TypeError,ValueError,KeyError):
        # Kodi can invalidate InfoTags between isPlayingVideo and identity().
        # Hold this exit while pending; never terminate the background service.
        value=state()
        if not value:return False
        if time.monotonic()>value['deadline']:
            value['phase']='failed';_save(value)
            if navigator is not None and not navigator._closed:navigator.close()
        _trace('PLAYER_UNAVAILABLE',value['session']);return True

"""Bounded local import history; counts come from committed existing guide tables.

No source URLs, event text, credentials or second EPG database. Reads run on a
worker, never on sender focus. A queued request is not a successful download.
"""
import contextlib,hashlib,json,os,re,sqlite3,tempfile,threading,time
from urllib.parse import quote
_local=threading.local()
SUCCESS={'READY','PARTIAL_PRESERVED','UNCHANGED','VERIFIED','READY_NO_NOW','PARTIAL_SUCCESS'}
BLOCKED={'BACKUP_REQUIRED','IMPORT_BUSY_OR_LOCK_UNAVAILABLE','WAIT_ACTIVE_CATALOG','CANCELLED','NO_NEW_GUIDE'}
MAX_BYTES=1048576


def path(pid):
    from utils import addon_data_dir
    return os.path.join(addon_data_dir(),'epg_history53_'+hashlib.sha256(str(pid).encode()).hexdigest()[:24]+'.json')


def history(pid):
    try:
        with open(path(pid),encoding='utf-8') as f:raw=f.read(MAX_BYTES+1)
        value=json.loads(raw) if len(raw)<=MAX_BYTES else {}
        return [r for r in value['runs'] if isinstance(r,dict)][-16:] if isinstance(value,dict) and value.get('version')==1 and isinstance(value.get('runs'),list) else []
    except (OSError,ValueError,KeyError,TypeError):return []


def store(pid,run):
    from profile_transaction import writing
    temp=None
    try:
        with writing(timeout=.1):
            runs=(history(pid)+[run])[-16:];raw=json.dumps(dict(version=1,runs=runs),ensure_ascii=False).encode()
            while len(raw)>MAX_BYTES and len(runs)>1:
                runs.pop(0);raw=json.dumps(dict(version=1,runs=runs),ensure_ascii=False).encode()
            if len(raw)>MAX_BYTES:return False
            target=path(pid)
            if os.path.islink(target):return False
            fd,temp=tempfile.mkstemp(prefix='.epg-history53-',dir=os.path.dirname(target))
            with os.fdopen(fd,'wb') as f:f.write(raw);f.flush();os.fsync(f.fileno())
            os.replace(temp,target);temp=None
        return True
    except (OSError,ValueError):return False
    finally:
        if temp:
            try:os.unlink(temp)
            except OSError:pass


def statistics(pid):
    from guide_store import path as guide_path
    filename=guide_path();db=None
    if not os.path.isfile(filename):return dict(code='NOT_CREATED',sources=[],programmes=0,first=None,last=None)
    try:
        db=sqlite3.connect('file:'+quote(filename,safe='/')+'?mode=ro',uri=True,timeout=.05)
        db.execute('PRAGMA query_only=ON');db.execute('BEGIN');end=time.monotonic()+1
        db.set_progress_handler(lambda:int(time.monotonic()>end),1000)
        row=db.execute('SELECT count(*),min(start),max(stop) FROM programmes WHERE pid=?',(str(pid),)).fetchone()
        sources=[dict(id=r[0],channels=r[1],programmes=r[2],first=r[3],last=r[4]) for r in db.execute('SELECT source_id,count(DISTINCT cid),count(*),min(start),max(stop) FROM guide44_inputs WHERE pid=? GROUP BY source_id LIMIT 129',(str(pid),))]
        if len(sources)>128:return dict(code='BUDGET',sources=[],programmes=None,first=None,last=None)
        return dict(code='READY',sources=sources,programmes=row[0],first=row[1],last=row[2])
    except (OSError,sqlite3.Error):return dict(code='UNAVAILABLE',sources=[],programmes=None,first=None,last=None)
    finally:
        if db is not None:db.close()


def started(pid,key,identity,rank):
    run=getattr(_local,'run',None)
    if not run or run['pid']!=str(pid):return
    if len(run['sources'])>=128:return
    run['sources'][identity]=dict(key=key,id=identity,rank=rank,started=time.time(),code='RUNNING')


def source_done(pid,identity,code,counts=None,outcome=None):
    run=getattr(_local,'run',None)
    if not run or run['pid']!=str(pid):return
    row=run['sources'].get(identity)
    if row is None:return
    row.update(code=code,finished=time.time());row['seconds']=round(row['finished']-row['started'],3)
    for key in ('channels','stored','bytes'):
        value=(counts or {}).get(key)
        if isinstance(value,(int,float)) and value>=0:row[key]=value
    for key in ('added','corrected','conflicts'):
        value=(outcome or {}).get(key)
        if isinstance(value,int) and value>=0:row[key]=value


@contextlib.contextmanager
def observing(pid,automatic=False):
    previous=getattr(_local,'run',None)
    run=dict(pid=str(pid),started=time.time(),automatic=bool(automatic),sources={},code='RUNNING')
    before=statistics(pid);_local.run=run
    try:yield run
    finally:
        try:
            from epg_status import read
            status=read(pid).get('refresh',{})
            if status.get('at',0)>=run['started']:run['code']=status.get('code','UNAVAILABLE')
            elif run.get('result'):run['code']='READY'
            else:run['code']='NO_NEW_GUIDE'
            run['finished']=time.time();run['seconds']=round(run['finished']-run['started'],3)
            after=statistics(pid);run['before']=before;run['after']=after
            stored={r['id']:r for r in after['sources']}
            for identity,row in run['sources'].items():
                if identity in stored:row['saved']=stored[identity]
                if row['code']=='RUNNING':row['code']='CANCELLED'
            run['sources']=list(run['sources'].values());run.pop('pid',None);run.pop('result',None)
            if not store(pid,run):
                from utils import warn
                warn('EPG53_REPORT_WRITE_FAILED')
        except Exception:pass  # Telemetry never converts a successful import to failure.
        finally:_local.run=previous


def label(value,fallback='XMLTV-Quelle'):
    value=str(value or '').replace('\n',' ').replace('\r',' ')[:100]
    if '://' in value or '@' in value or re.search(r'(?i)(password|passwort|token|username)\s*[=:]',value):return fallback
    return value or fallback


def stamp(value):return time.strftime('%d.%m.%Y %H:%M',time.localtime(value)) if value else 'noch nicht bestätigt'


def meaning(code):
    return {'STATUS_UNVERIFIED':'Früherer Status nicht durch gespeicherte Daten bestätigt','NO_SAVED_PROGRAMMES':'Noch keine gespeicherten Sendungen bestätigt','READY':'Erfolgreich gespeichert','READY_NO_NOW':'Gespeichert; aktuell keine laufende Sendung','PARTIAL_SUCCESS':'Teilweise erfolgreich','PARTIAL_PRESERVED':'Gespeichert; widersprüchliche Einträge geschützt','UNCHANGED':'Unverändert bestätigt','BACKUP_REQUIRED':'Verifizierte EPG-Sicherung erforderlich','WAIT_ACTIVE_CATALOG':'Senderkatalog noch nicht bereit','NO_NEW_GUIDE':'Keine neue gültige Programmliste','CANCELLED':'Abgebrochen; bisherige Daten bleiben erhalten','IMPORT_BUSY_OR_LOCK_UNAVAILABLE':'Ein EPG-Import läuft bereits','RUNNING':'Wird aktualisiert','DISABLED':'Deaktiviert','WAITING':'Noch kein Lauf bestätigt'}.get(code,'Aktualisierung fehlgeschlagen; bisherige Daten bleiben erhalten')


def advice(code):
    if code in SUCCESS:return 'Fehlende Tage oder Bilder können von der Quelle fehlen. Gespeicherten Zeitraum unten prüfen.'
    if code=='BACKUP_REQUIRED':return 'Die vorhandene EPG-Sicherungsfunktion ausführen und BACKUP_VERIFIED abwarten. Keine Datenbank löschen.'
    if code=='WAIT_ACTIVE_CATALOG':return 'Zuerst den vorhandenen Senderkatalog fertig laden lassen.'
    if code=='IMPORT_BUSY_OR_LOCK_UNAVAILABLE':return 'Laufenden Import abwarten; keine zweite Aktualisierung starten.'
    return 'Quelle, Internetverbindung und freien Speicher prüfen. Später gezielt erneut versuchen; keine Daten zurücksetzen.'


def configured(portal):
    from epg_sources import configuration
    from guide_publish44 import source_id
    result=[dict(id='provider',key='provider',name='Anbieter-EPG',rank=0,enabled=portal.get('provider_epg_enabled',True))]
    for rank,s in enumerate(configuration(portal['id'])['sources'],1):
        result.append(dict(id=source_id(s,rank),key=__import__('epg_status').source_key(s),name=label(s.get('name')),rank=rank,enabled=s.get('enabled',True),record=s))
    return result


def overview(portal):
    from epg_status import read
    stats=statistics(portal['id']);runs=history(portal['id']);state=read(portal['id']);rows=[]
    for item in configured(portal):
        row=dict(item);events=[s for run in runs for s in run.get('sources',[]) if s.get('id')==item['id']]
        saved=next((s for s in stats['sources'] if s['id']==item['id']),{})
        legacy=state.get(item['key'],{});last=events[-1] if events else legacy
        row.update(code=last.get('code','WAITING') if item['enabled'] else 'DISABLED',saved=saved,statistics_code=stats['code'])
        if row['code'] in SUCCESS:
            if stats['code']!='READY':row['code']='STATUS_UNVERIFIED'
            elif not saved.get('programmes'):row['code']='NO_SAVED_PROGRAMMES'
        row['last_success']=max([s.get('finished',0) for s in events if s.get('code') in SUCCESS]+[legacy.get('last_success',0)])
        row['last_failure']=max([s.get('finished',0) for s in events if s.get('code') not in SUCCESS]+[0])
        rows.append(row)
    return rows


def describe(run,portal):
    names={r['id']:r['name'] for r in configured(portal)}
    lines=['Automatische Aktualisierung' if run.get('automatic') else 'Manuelle Aktualisierung',
           'Beginn: '+stamp(run.get('started')),'Dauer: '+str(run.get('seconds',0))+' Sekunden',meaning(run.get('code')),'',advice(run.get('code'))]
    after=run.get('after',{});before=run.get('before',{})
    if after.get('code')=='READY':
        lines+=['','Gespeicherte Programme: '+str(after['programmes']),'Zeitraum: '+stamp(after.get('first'))+' bis '+stamp(after.get('last'))]
        if before.get('programmes') is not None:lines.append('Bestand vorher / nachher: '+str(before['programmes'])+' / '+str(after['programmes']))
    else:lines+=['','Gespeicherter Zeitraum derzeit nicht sicher lesbar. Keine Aussage über fehlende Daten.']
    sources=run.get('sources',[]);good=sum(s.get('code') in SUCCESS for s in sources)
    lines+=['','Quellen: '+str(good)+' erfolgreich, '+str(len(sources)-good)+' nicht erfolgreich']
    for s in sources:
        lines+=['','[B]'+names.get(s['id'],'Früher konfigurierte Quelle')+'[/B]',meaning(s.get('code')),
                'Geladen: '+str(s.get('channels',0))+' Sender / '+str(s.get('stored',0))+' passende Sendungen',
                'Dauer: '+str(s.get('seconds',0))+' Sekunden']
        saved=s.get('saved',{})
        if saved:lines+=['Gespeichert: '+str(saved.get('channels',0))+' Sender / '+str(saved.get('programmes',0))+' Sendungen',stamp(saved.get('first'))+' bis '+stamp(saved.get('last'))]
        if any(k in s for k in ('added','corrected','conflicts')):lines.append('Neu: '+str(s.get('added',0))+' · aktualisiert: '+str(s.get('corrected',0))+' · Konflikte bewahrt: '+str(s.get('conflicts',0)))
        if s.get('code') not in SUCCESS:lines.append(advice(s.get('code')))
    return '\n'.join(lines)

